# SAME-SCENARIO\n\"\"\"\ncompare_metric_series.py\nCompare metric values for two resources or dimension filters over the same window.\n\"\"\"\n\nfrom observability_client import ManagedMetricsClient\n\ndef compare_metric_series(metric_name: str, resource_a: str, resource_b: str, start_time: str, end_time: str) -> list:\n    \"\"\"Compare two series by fetching each series and aligning timestamps.\n\n    Returns a list of dicts with fields: timestamp, value_a, value_b, delta.\n    \"\"\"\n    client = ManagedMetricsClient()\n    return client.compare_metric_series(metric_name, resource_a, resource_b, start_time, end_time)
